import unittest
from candidate import largest_prime_factor


class TestLargestPrimeFactor(unittest.TestCase):
    def test_smallest_composite(self):
        self.assertEqual(largest_prime_factor(4), 2)

    def test_six(self):
        self.assertEqual(largest_prime_factor(6), 3)

    def test_eight(self):
        self.assertEqual(largest_prime_factor(8), 2)

    def test_nine(self):
        self.assertEqual(largest_prime_factor(9), 3)

    def test_ten(self):
        self.assertEqual(largest_prime_factor(10), 5)

    def test_twelve(self):
        self.assertEqual(largest_prime_factor(12), 3)

    def test_fifteen(self):
        self.assertEqual(largest_prime_factor(15), 5)

    def test_twenty_five(self):
        self.assertEqual(largest_prime_factor(25), 5)

    def test_forty_nine(self):
        self.assertEqual(largest_prime_factor(49), 7)

    def test_seventy_seven(self):
        self.assertEqual(largest_prime_factor(77), 11)

    def test_hundred(self):
        self.assertEqual(largest_prime_factor(100), 5)

    def test_two_thousand_fifty_eight(self):
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_thirteen_thousand_one_hundred_ninety_five(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_two_thousand_one_hundred(self):
        self.assertEqual(largest_prime_factor(210), 7)

    def test_one_thousand_twenty_four(self):
        self.assertEqual(largest_prime_factor(1024), 2)

    def test_eighty_one(self):
        self.assertEqual(largest_prime_factor(81), 3)

    def test_two_hundred_fifty(self):
        self.assertEqual(largest_prime_factor(250), 5)

    def test_one_thousand(self):
        self.assertEqual(largest_prime_factor(1000), 5)

    def test_product_of_two_primes(self):
        self.assertEqual(largest_prime_factor(14), 7)

    def test_product_of_three_primes(self):
        self.assertEqual(largest_prime_factor(30), 5)

    def test_prime_power_of_two(self):
        self.assertEqual(largest_prime_factor(16), 2)

    def test_prime_power_of_three(self):
        self.assertEqual(largest_prime_factor(27), 3)

    def test_prime_power_of_seven(self):
        self.assertEqual(largest_prime_factor(343), 7)

    def test_large_composite(self):
        self.assertEqual(largest_prime_factor(10000), 5)

    def test_two_hundred_seventy_eight(self):
        self.assertEqual(largest_prime_factor(278), 139)

    def test_six_hundred_sixty(self):
        self.assertEqual(largest_prime_factor(660), 11)

    def test_twelve_hundred_sixty(self):
        self.assertEqual(largest_prime_factor(1260), 7)

    def test_n_less_than_two_raises_or_returns(self):
        with self.assertRaises(Exception):
            largest_prime_factor(1)

    def test_n_zero(self):
        with self.assertRaises(Exception):
            largest_prime_factor(0)

    def test_n_negative(self):
        with self.assertRaises(Exception):
            largest_prime_factor(-10)

    def test_n_none(self):
        with self.assertRaises(Exception):
            largest_prime_factor(None)

    def test_n_string(self):
        with self.assertRaises(Exception):
            largest_prime_factor("12")

    def test_n_float(self):
        with self.assertRaises(Exception):
            largest_prime_factor(12.5)

    def test_n_boolean(self):
        with self.assertRaises(Exception):
            largest_prime_factor(True)

    def test_n_list(self):
        with self.assertRaises(Exception):
            largest_prime_factor([2, 3, 5])

    def test_returns_integer_type(self):
        result = largest_prime_factor(12)
        self.assertIsInstance(result, int)

    def test_composite_with_large_prime_factor(self):
        self.assertEqual(largest_prime_factor(2 * 97), 97)

    def test_composite_with_repeated_factors(self):
        self.assertEqual(largest_prime_factor(2 * 2 * 3 * 3), 3)

    def test_composite_220(self):
        self.assertEqual(largest_prime_factor(220), 11)

    def test_composite_330(self):
        self.assertEqual(largest_prime_factor(330), 11)


if __name__ == '__main__':
    unittest.main()
